          {
            "role": "CTO",
            "background": "Formerly built real-time pricing engines at DoorDash; ML/privacy-crypto background"
          },
          {
            "role": "Head of Partnerships",
            "background": "10 years in hospitality tech; deep relationships with multi-unit restaurant groups"
          }
        ]
      },
      "9_traction_and_validation": {
        "heading": "Traction",
        "content": "1,200 beta users across 3 cities in 6 weeks. 74% weekly retention. 38% of beta diners returned to check a tip benchmark within 48 hours of dining. 4 restaurant groups (12 locations total) signed LOIs for the Insights Dashboard. NPS of 62 among early adopters."
      },
      "10_the_ask": {
